INSERT INTO repo_modules (module_id, name, module_no, description, module_sd_id, status) VALUES ('MOD_COURSE_036_M2', 'Actuators and Drives', '2', 'Examines the concepts and methods required to understand and work with actuators and drives. The module addresses DC motors, stepper motors, servo drives, solenoids, and pneumatic and hydraulic actuators, with emphasis on their relationships, assumptions, analytical use, and application within Mechatronics.', 'MSD_COURSE_036_M2', 'Active'), ('MOD_COURSE_036_M3', 'Embedded Controllers', '3', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour embedded controllers. The module addresses microcontrollers, I/O, timers, interrupts, ADC/DAC, and real-time execution, with emphasis on their relationships, assumptions, analytical use, and application within Mechatronics.', 'MSD_COURSE_036_M3', 'Active'), ('MOD_COURSE_036_M4', 'Signal Conditioning and Data Acquisition', '4', 'Examines the concepts and methods required to understand and work with signal conditioning and data acquisition. The module addresses amplification, filtering, isolation, sampling, and data acquisition, with emphasis on their relationships, assumptions, analytical use, and application within Mechatronics.', 'MSD_COURSE_036_M4', 'Active'), ('MOD_COURSE_036_M5', 'System Modelling and Control', '5', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour system modelling and control. The module addresses dynamic models, transfer functions, state-space, feedback, and PID control, with emphasis on their relationships, assumptions, analytical use, and application within Mechatronics.', 'MSD_COURSE_036_M5', 'Active'), ('MOD_COURSE_036_M6', 'Mechatronic System Integration', '6', 'Examines the concepts and methods required to understand and work with mechatronic system integration. The module addresses mechanical-electrical interfaces, embedded software, control architecture, and system integration, with emphasis on their relationships, assumptions, analytical use, and application within Mechatronics.', 'MSD_COURSE_036_M6', 'Active'), ('MOD_COURSE_036_M7', 'Testing and Reliability of Mechatronic Systems', '7', 'Examines how the relevant components are organised into functioning systems and how their interactions constrain performance testing and reliability of mechatronic systems. The module addresses verification, validation, fault diagnosis, calibration, and reliability testing, with emphasis on their relationships, assumptions, analytical use, and application within Mechatronics.', 'MSD_COURSE_036_M7', 'Active'), ('MOD_COURSE_037_M1', 'Refrigeration Cycles', '1', 'Examines the concepts and methods required to understand and work with refrigeration cycles. The module addresses vapour-compression cycle, refrigeration effect, COP, and pressure-enthalpy analysis, with emphasis on their relationships, assumptions, analytical use, and application within Refrigeration and Air Conditioning.', 'MSD_COURSE_037_M1', 'Active'), ('MOD_COURSE_037_M2', 'Refrigerants and Environmental Considerations', '2', 'Examines the concepts and methods required to understand and work with refrigerants and environmental considerations. The module addresses refrigerant properties, classification, safety, and phase-out and alternatives, with emphasis on their relationships, assumptions, analytical use, and application within Refrigeration and Air Conditioning.', 'MSD_COURSE_037_M2', 'Active'), ('MOD_COURSE_037_M3', 'Refrigeration Components', '3', 'Examines the constituent materials or components, their properties, and their influence on system performance refrigeration components. The module addresses compressors, condensers, expansion devices, evaporators, and controls, with emphasis on their relationships, assumptions, analytical use, and application within Refrigeration and Air Conditioning.', 'MSD_COURSE_037_M3', 'Active'), ('MOD_COURSE_037_M4', 'Psychrometrics', '4', 'Examines the concepts and methods required to understand and work with psychrometrics. The module addresses humidity ratio, relative humidity, psychrometric chart, air mixing, and dew point, with emphasis on their relationships, assumptions, analytical use, and application within Refrigeration and Air Conditioning.', 'MSD_COURSE_037_M4', 'Active'), ('MOD_COURSE_037_M5', 'Air-Conditioning Loads', '5', 'Examines the concepts and methods required to understand and work with air-conditioning loads. The module addresses sensible and latent loads, heat gains, ventilation, infiltration, and load calculation, with emphasis on their relationships, assumptions, analytical use, and application within Refrigeration and Air Conditioning.', 'MSD_COURSE_037_M5', 'Active'), ('MOD_COURSE_037_M6', 'Air-Conditioning Systems', '6', 'Examines how the relevant components are organised into functioning systems and how their interactions constrain performance air-conditioning systems. The module addresses all-air systems, chilled-water systems, variable air volume, and equipment selection, with emphasis on their relationships, assumptions, analytical use, and application within Refrigeration and Air Conditioning.', 'MSD_COURSE_037_M6', 'Active'), ('MOD_COURSE_037_M7', 'System Performance and Diagnostics', '7', 'Examines the concepts and methods required to understand and work with system performance and diagnostics. The module addresses COP/EER, part-load performance, commissioning, fault diagnosis, and maintenance, with emphasis on their relationships, assumptions, analytical use, and application within Refrigeration and Air Conditioning.', 'MSD_COURSE_037_M7', 'Active'), ('MOD_COURSE_038_M1', 'Engine Cycles and Architecture', '1', 'Examines how the relevant components are organised into functioning systems and how their interactions constrain performance engine cycles and architecture. The module addresses Otto cycle, Diesel cycle, dual cycle, two-stroke/four-stroke, and engine configurations, with emphasis on their relationships, assumptions, analytical use, and application within Internal Combustion Engines.', 'MSD_COURSE_038_M1', 'Active'), ('MOD_COURSE_038_M2', 'Engine Components and Mechanics', '2', 'Examines the constituent materials or components, their properties, and their influence on system performance engine components and mechanics. The module addresses cylinder, piston, crankshaft, valve train, lubrication, and cooling, with emphasis on their relationships, assumptions, analytical use, and application within Internal Combustion Engines.', 'MSD_COURSE_038_M2', 'Active'), ('MOD_COURSE_038_M3', 'Air and Fuel Systems', '3', 'Examines how the relevant components are organised into functioning systems and how their interactions constrain performance air and fuel systems. The module addresses air intake, turbocharging, fuel injection, ignition, and mixture formation, with emphasis on their relationships, assumptions, analytical use, and application within Internal Combustion Engines.', 'MSD_COURSE_038_M3', 'Active'), ('MOD_COURSE_038_M4', 'Combustion in Engines', '4', 'Examines the concepts and methods required to understand and work with combustion in engines. The module addresses flame development, ignition delay, knock, combustion efficiency, and heat release, with emphasis on their relationships, assumptions, analytical use, and application within Internal Combustion Engines.', 'MSD_COURSE_038_M4', 'Active'), ('MOD_COURSE_038_M5', 'Engine Performance', '5', 'Examines the concepts and methods required to understand and work with engine performance. The module addresses brake power, indicated power, efficiency, specific fuel consumption, and performance testing, with emphasis on their relationships, assumptions, analytical use, and application within Internal Combustion Engines.', 'MSD_COURSE_038_M5', 'Active'), ('MOD_COURSE_038_M6', 'Emissions and After-Treatment', '6', 'Examines the concepts and methods required to understand and work with emissions and after-treatment. The module addresses NOx, particulate matter, CO, hydrocarbons, oxidation catalysts, and particulate filters, with emphasis on their relationships, assumptions, analytical use, and application within Internal Combustion Engines.', 'MSD_COURSE_038_M6', 'Active'), ('MOD_COURSE_038_M7', 'Engine Control and Diagnostics', '7', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour engine control and diagnostics. The module addresses electronic control, sensors, actuators, diagnostics, and calibration, with emphasis on their relationships, assumptions, analytical use, and application within Internal Combustion Engines.', 'MSD_COURSE_038_M7', 'Active'), ('MOD_COURSE_039_M1', 'Material Structure and Properties', '1', 'Examines the concepts and methods required to understand and work with material structure and properties. The module addresses crystal structures, defects, diffusion, phase structure, and mechanical properties, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Materials.', 'MSD_COURSE_039_M1', 'Active'), ('MOD_COURSE_039_M2', 'Ferrous Materials', '2', 'Examines the constituent materials or components, their properties, and their influence on system performance ferrous materials. The module addresses steels, cast irons, phase transformations, heat treatment, and alloying, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Materials.', 'MSD_COURSE_039_M2', 'Active'), ('MOD_COURSE_039_M3', 'Non-Ferrous Materials', '3', 'Examines the constituent materials or components, their properties, and their influence on system performance non-ferrous materials. The module addresses aluminium, copper, titanium, nickel alloys, and selection criteria, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Materials.', 'MSD_COURSE_039_M3', 'Active'), ('MOD_COURSE_039_M4', 'Polymers and Ceramics', '4', 'Examines the concepts and methods required to understand and work with polymers and ceramics. The module addresses thermoplastics, thermosets, elastomers, ceramics, and processing-property relations, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Materials.', 'MSD_COURSE_039_M4', 'Active'), ('MOD_COURSE_039_M5', 'Composite Materials', '5', 'Examines the constituent materials or components, their properties, and their influence on system performance composite materials. The module addresses fibres, matrices, laminates, anisotropy, and failure mechanisms, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Materials.', 'MSD_COURSE_039_M5', 'Active'), ('MOD_COURSE_039_M6', 'Material Processing', '6', 'Examines the concepts and methods required to understand and work with material processing. The module addresses casting, forming, machining, joining, and additive manufacturing, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Materials.', 'MSD_COURSE_039_M6', 'Active'), ('MOD_COURSE_039_M7', 'Material Selection and Failure', '7', 'Examines the concepts and methods required to understand and work with material selection and failure. The module addresses Ashby-style selection, corrosion, fatigue, fracture, wear, and failure analysis, with emphasis on their relationships, assumptions, analytical use, and application within Engineering Materials.', 'MSD_COURSE_039_M7', 'Active'), ('MOD_COURSE_040_M1', 'Units, Dimensions and Process Variables', '1', 'Examines the concepts and methods required to understand and work with units, dimensions and process variables. The module addresses SI units, dimensional consistency, concentration, flow rates, pressure, and temperature, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Process Calculations.', 'MSD_COURSE_040_M1', 'Active'), ('MOD_COURSE_040_M2', 'Material Balances', '2', 'Examines the concepts and methods required to understand and work with material balances. The module addresses mass conservation, component balances, basis selection, recycle, and purge, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Process Calculations.', 'MSD_COURSE_040_M2', 'Active'), ('MOD_COURSE_040_M3', 'Balances with Chemical Reactions', '3', 'Examines the concepts and methods required to understand and work with balances with chemical reactions. The module addresses stoichiometry, conversion, yield, selectivity, and extent of reaction, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Process Calculations.', 'MSD_COURSE_040_M3', 'Active'), ('MOD_COURSE_040_M4', 'Energy Balances', '4', 'Examines the concepts and methods required to understand and work with energy balances. The module addresses enthalpy, heat capacity, phase change, heat effects, and steady-state energy balances, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Process Calculations.', 'MSD_COURSE_040_M4', 'Active'), ('MOD_COURSE_040_M5', 'Combined Material and Energy Balances', '5', 'Examines the concepts and methods required to understand and work with combined material and energy balances. The module addresses coupled balances, process streams, heat integration basics, and degrees of freedom, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Process Calculations.', 'MSD_COURSE_040_M5', 'Active'), ('MOD_COURSE_040_M6', 'Process Flow Calculations', '6', 'Examines the concepts and methods required to understand and work with process flow calculations. The module addresses flowsheets, stream tables, process specifications, numerical solution, and sensitivity, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Process Calculations.', 'MSD_COURSE_040_M6', 'Active'), ('MOD_COURSE_041_M1', 'Fluid Properties and Flow Fundamentals', '1', 'Establishes the foundational models, terminology, and governing principles fluid properties and flow fundamentals. The module addresses density, viscosity, Newtonian fluids, hydrostatics, and pressure measurement, with emphasis on their relationships, assumptions, analytical use, and application within Fluid Flow and Heat Transfer.', 'MSD_COURSE_041_M1', 'Active'), ('MOD_COURSE_041_M2', 'Internal Flow', '2', 'Examines the concepts and methods required to understand and work with internal flow. The module addresses laminar flow, turbulent flow, friction factor, pipe fittings, and pumping requirements, with emphasis on their relationships, assumptions, analytical use, and application within Fluid Flow and Heat Transfer.', 'MSD_COURSE_041_M2', 'Active'), ('MOD_COURSE_041_M3', 'External Flow and Boundary Layers', '3', 'Examines the concepts and methods required to understand and work with external flow and boundary layers. The module addresses drag, boundary layers, flow separation, and pressure drop, with emphasis on their relationships, assumptions, analytical use, and application within Fluid Flow and Heat Transfer.', 'MSD_COURSE_041_M3', 'Active'), ('MOD_COURSE_041_M4', 'Momentum Transport and Dimensional Analysis', '4', 'Develops the analytical methods used to formulate, solve, and evaluate problems momentum transport and dimensional analysis. The module addresses momentum balance, dimensional groups, similitude, and scale-up, with emphasis on their relationships, assumptions, analytical use, and application within Fluid Flow and Heat Transfer.', 'MSD_COURSE_041_M4', 'Active'), ('MOD_COURSE_041_M5', 'Heat Conduction and Convection', '5', 'Examines the concepts and methods required to understand and work with heat conduction and convection. The module addresses Fourier law, steady conduction, transient conduction, and natural and forced convection, with emphasis on their relationships, assumptions, analytical use, and application within Fluid Flow and Heat Transfer.', 'MSD_COURSE_041_M5', 'Active'), ('MOD_COURSE_041_M6', 'Heat Exchangers', '6', 'Examines the concepts and methods required to understand and work with heat exchangers. The module addresses LMTD, effectiveness-NTU, exchanger configurations, fouling, and design, with emphasis on their relationships, assumptions, analytical use, and application within Fluid Flow and Heat Transfer.', 'MSD_COURSE_041_M6', 'Active'), ('MOD_COURSE_041_M7', 'Radiation and Thermal Systems', '7', 'Examines how the relevant components are organised into functioning systems and how their interactions constrain performance radiation and thermal systems. The module addresses thermal radiation, emissivity, view factors, combined modes, and insulation, with emphasis on their relationships, assumptions, analytical use, and application within Fluid Flow and Heat Transfer.', 'MSD_COURSE_041_M7', 'Active'), ('MOD_COURSE_042_M1', 'Diffusion and Mass-Transfer Fundamentals', '1', 'Establishes the foundational models, terminology, and governing principles diffusion and mass-transfer fundamentals. The module addresses Fick law, molecular diffusion, mass-transfer coefficients, and interfacial transport, with emphasis on their relationships, assumptions, analytical use, and application within Mass Transfer Operations.', 'MSD_COURSE_042_M1', 'Active'), ('MOD_COURSE_042_M2', 'Gas Absorption and Stripping', '2', 'Examines the concepts and methods required to understand and work with gas absorption and stripping. The module addresses equilibrium relations, operating lines, HTU/NTU, and packed columns, with emphasis on their relationships, assumptions, analytical use, and application within Mass Transfer Operations.', 'MSD_COURSE_042_M2', 'Active'), ('MOD_COURSE_042_M3', 'Distillation', '3', 'Examines the concepts and methods required to understand and work with distillation. The module addresses vapour-liquid equilibrium, McCabe-Thiele, reflux, tray efficiency, and multicomponent concepts, with emphasis on their relationships, assumptions, analytical use, and application within Mass Transfer Operations.', 'MSD_COURSE_042_M3', 'Active'), ('MOD_COURSE_042_M4', 'Liquid-Liquid Extraction', '4', 'Examines the concepts and methods required to understand and work with liquid-liquid extraction. The module addresses distribution coefficients, ternary diagrams, stagewise extraction, and solvent selection, with emphasis on their relationships, assumptions, analytical use, and application within Mass Transfer Operations.', 'MSD_COURSE_042_M4', 'Active'), ('MOD_COURSE_042_M5', 'Humidification and Drying', '5', 'Examines the concepts and methods required to understand and work with humidification and drying. The module addresses psychrometrics, wet-bulb temperature, drying curves, and drying-rate periods, with emphasis on their relationships, assumptions, analytical use, and application within Mass Transfer Operations.', 'MSD_COURSE_042_M5', 'Active'), ('MOD_COURSE_042_M6', 'Adsorption and Membrane Separation', '6', 'Examines the concepts and methods required to understand and work with adsorption and membrane separation. The module addresses adsorption equilibria, breakthrough, membrane transport, selectivity, and permeability, with emphasis on their relationships, assumptions, analytical use, and application within Mass Transfer Operations.', 'MSD_COURSE_042_M6', 'Active'), ('MOD_COURSE_042_M7', 'Mass-Transfer Equipment Design', '7', 'Develops the design methods and decision criteria used to translate theory into an engineered or applied solution mass-transfer equipment design. The module addresses column hydraulics, flooding, pressure drop, scale-up, and process integration, with emphasis on their relationships, assumptions, analytical use, and application within Mass Transfer Operations.', 'MSD_COURSE_042_M7', 'Active'), ('MOD_COURSE_043_M1', 'Reaction Kinetics', '1', 'Examines the concepts and methods required to understand and work with reaction kinetics. The module addresses rate laws, reaction order, Arrhenius equation, elementary reactions, and kinetic parameter estimation, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Reaction Engineering.', 'MSD_COURSE_043_M1', 'Active'), ('MOD_COURSE_043_M2', 'Ideal Reactors', '2', 'Examines the concepts and methods required to understand and work with ideal reactors. The module addresses batch reactors, CSTR, PFR, reactor design equations, and residence time, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Reaction Engineering.', 'MSD_COURSE_043_M2', 'Active'), ('MOD_COURSE_043_M3', 'Multiple Reactions', '3', 'Examines the concepts and methods required to understand and work with multiple reactions. The module addresses parallel reactions, series reactions, selectivity, yield, and reaction networks, with emphasis on their relationships, assumptions, analytical use, and application within Chemical Reaction Engineering.', 'MSD_COURSE_043_M3', 'Active') ON CONFLICT DO NOTHING;